/* Generated from the game data (ui_text.csv + UnitData). Do not edit by hand. */
window.MAID_DATA = {"jobs":[{"key":"sword","name":{"ko":"검","en":"Sword","ja":"剣"},"maids":[{"id":"Chiyo","stats":{"hp":340.0,"atk":66.0,"aspd":0.385,"range":1.5,"speed":3.4,"cost":70},"name":{"ko":"치요","en":"Chiyo","ja":"チヨ"},"bio":{"ko":"생각하기 전에 몸부터 움직이는 타입의 메이드. 조금 단순한 구석이 있지만, 웬만한 일에는 기죽지 않는 낙천적인 성격이다. 사고를 치고도 \"뭐, 어떻게든 되겠지!\" 하며 웃어넘기는 경우가 많다.","en":"A maid who moves before she thinks. A little simple, perhaps, but almost nothing gets her down. Even after causing a mess she tends to laugh it off with a \"Well, it'll work out somehow!\"","ja":"考えるより先に体が動くタイプのメイド。少し単純なところはあるが、たいていのことでは落ち込まない楽天家。やらかした後も「まあ、なんとかなるでしょ!」と笑ってすませることが多い。"},"ability":{"ko":"공격력과 체력이 균형 잡힌 기본형 근접 전투원. 특별한 조건 없이 꾸준히 전투를 이어간다.","en":"A baseline melee fighter with balanced attack and health. She keeps fighting steadily, with no special conditions attached.","ja":"攻撃力と体力のバランスが取れた基本形の近接戦闘員。特別な条件なしに安定して戦い続ける。"},"img":"sword_01","r":0,"timing":[0.4,1.3]},{"id":"Sword_02","stats":{"hp":500.0,"atk":88.0,"aspd":0.4,"range":1.6,"speed":3.4,"cost":105},"name":{"ko":"카에데","en":"Kaede","ja":"カエデ"},"bio":{"ko":"무슨 일이든 귀찮다는 듯한 얼굴을 하고 있지만, 막상 맡은 일은 묵묵히 끝까지 해낸다. 쓸데없는 말이나 행동을 싫어해서 전투에서도 최소한의 움직임만 보여준다.","en":"She wears the face of someone who finds everything a chore, yet she sees every task she takes on quietly through to the end. She dislikes wasted words and wasted motion, so in battle she moves only as much as she has to.","ja":"何をするにも面倒くさそうな顔をしているが、引き受けた仕事は黙々と最後までやり遂げる。無駄な言葉も動きも嫌いなので、戦闘でも必要最低限しか動かない。"},"ability":{"ko":"네 번째 공격마다 강력한 일격을 가한다. 평소에는 차분하게 공격을 이어가다가 한 번씩 높은 피해를 만들어낸다.","en":"Every fourth attack lands as a powerful blow. She keeps a calm rhythm going, then spikes into high damage now and then.","ja":"四回目の攻撃ごとに強烈な一撃を放つ。普段は落ち着いて攻撃を重ね、時折大きなダメージを生み出す。"},"img":"sword_02","r":1,"timing":[0.4,1.3]},{"id":"Sword_03","stats":{"hp":700.0,"atk":112.0,"aspd":0.435,"range":1.7,"speed":3.5,"cost":155},"name":{"ko":"츠바키","en":"Tsubaki","ja":"ツバキ"},"bio":{"ko":"언제나 무표정한 얼굴로 어딘가 멍하니 바라보고 있는 메이드. 관심이 없는 것처럼 보여도 은근히 주변을 신경 쓰고 있으며, 가끔 무심하게 건네는 한마디에 묘한 다정함이 묻어난다.","en":"A maid forever staring into the middle distance with no expression at all. She looks uninterested, but she quietly keeps track of everyone around her, and the offhand remarks she drops now and then carry a strange kind of warmth.","ja":"いつも無表情のまま、どこか遠くをぼんやり眺めているメイド。興味がなさそうに見えて、実はさりげなく周りを気にかけており、時折そっけなく口にする一言に妙な優しさがにじむ。"},"ability":{"ko":"두 번째 공격마다 강력한 일격을 가한다. 높은 공격력과 체력을 바탕으로 전선에서 꾸준한 화력을 낸다.","en":"Every second attack lands as a powerful blow. High attack and health let her hold the line with steady firepower.","ja":"二回目の攻撃ごとに強烈な一撃を放つ。高い攻撃力と体力を背景に、前線で安定した火力を出す。"},"img":"sword_03","r":2,"timing":[0.4,1.3]}]},{"key":"lence","name":{"ko":"창","en":"Lancer","ja":"槍"},"maids":[{"id":"Lance_01","stats":{"hp":400.0,"atk":62.0,"aspd":0.385,"range":2.4,"speed":2.6,"cost":105},"name":{"ko":"레이","en":"Rei","ja":"レイ"},"bio":{"ko":"가늘게 뜬 눈과 차가운 표정 때문에 쉽게 다가가기 어려운 메이드. 감정을 좀처럼 겉으로 드러내지 않아 무슨 생각을 하는지 알기 어렵지만, 전투에서는 한 치의 망설임도 보이지 않는다.","en":"Narrowed eyes and a cold expression make her hard to approach. She rarely lets anything show, so what she is thinking is anyone's guess — but in battle there is not a moment's hesitation in her.","ja":"細めた目と冷たい表情のせいで、なかなか近寄りがたいメイド。感情をめったに表に出さないので何を考えているのか分かりにくいが、戦いでは一切のためらいを見せない。"},"ability":{"ko":"긴 사거리로 적보다 먼저 공격하고, 적을 뒤로 밀어낸다. 적의 접근을 막으며 안정적으로 거리를 유지한다.","en":"Her long reach lets her strike before the enemy can and shove them back. She shuts down approaches and keeps her distance steadily.","ja":"長い射程で敵より先に攻撃し、敵を後方へ押し出す。敵の接近を防ぎながら安定して距離を保つ。"},"img":"lence_01","r":0,"timing":[0.4,1.3]},{"id":"Ran","stats":{"hp":560.0,"atk":80.0,"aspd":0.417,"range":2.5,"speed":2.6,"cost":145},"name":{"ko":"란","en":"Ran","ja":"ラン"},"bio":{"ko":"툴툴거리는 말투와는 달리 누구보다 주변을 잘 챙기는 츤데레 메이드. 칭찬이나 관심을 받으면 얼굴부터 붉히면서도, 정작 중요한 순간에는 가장 먼저 나선다.","en":"For all her grumbling, no one looks after the others better than she does. Praise or attention turns her red in the face, yet when it really matters she is always the first to step forward.","ja":"口ではぶつぶつ言うくせに、誰よりも周りをよく気にかけているツンデレメイド。褒められたり構われたりすると真っ先に顔を赤くするが、肝心なときには誰より先に前へ出る。"},"ability":{"ko":"긴 랜스로 적보다 먼저 공격하는 선봉형 전투원. 높은 사거리와 회피 능력으로 비교적 안전하게 전투를 이어간다.","en":"A vanguard fighter whose long lance strikes before the enemy can. Good reach and evasion let her fight on in relative safety.","ja":"長いランスで敵より先に攻撃する先鋒型の戦闘員。長い射程と回避能力で、比較的安全に戦い続ける。"},"img":"lence_02","r":1,"timing":[0.4,1.3]},{"id":"Lance_03","stats":{"hp":700.0,"atk":100.0,"aspd":0.435,"range":2.8,"speed":2.6,"cost":180},"name":{"ko":"카구라","en":"Kagura","ja":"カグラ"},"bio":{"ko":"복잡하게 생각하는 것보다 직접 부딪혀 보는 걸 좋아하는 메이드. 호전적인 성격이라 강한 상대를 만나면 오히려 기분이 좋아져 먼저 달려든다.","en":"She would rather throw herself at a problem than think it through. Spoiling for a fight by nature, she only cheers up when a strong opponent shows up — and then she is the first to charge in.","ja":"ごちゃごちゃ考えるより、まず自分でぶつかってみるのが好きなメイド。好戦的な性格なので、強い相手に出くわすとむしろ機嫌が良くなり、自分から先に飛び込んでいく。"},"ability":{"ko":"적보다 먼저 공격하며 전선을 빠르게 압박하는 선봉형 전투원. 공격적인 플레이에 특화되어 있다.","en":"A vanguard fighter who strikes first and pushes the line forward fast. Built for aggressive play.","ja":"敵より先に攻撃し、前線を素早く押し上げる先鋒型の戦闘員。攻撃的な立ち回りに特化している。"},"img":"lence_03","r":2,"timing":[0.4,1.3]}]},{"key":"shield","name":{"ko":"방패","en":"Shield","ja":"盾"},"maids":[{"id":"Shion","stats":{"hp":620.0,"atk":20.0,"aspd":0.357,"range":1.5,"speed":2.0,"cost":60},"name":{"ko":"시온","en":"Shion","ja":"シオン"},"bio":{"ko":"늘 조금 주눅 들어 있고 자신감도 부족한 메이드. 그래도 자신이 지켜야 할 곳만큼은 끝까지 지키며, 힘든 상황에서도 조용히 버텨낸다.","en":"A maid who always seems a little cowed and short on confidence. Even so, the ground she has been told to hold she holds to the last, enduring quietly however hard things get.","ja":"いつも少し萎縮していて自信も足りないメイド。それでも自分が守るべき場所だけは最後まで守り抜き、苦しい状況でも静かに耐え続ける。"},"ability":{"ko":"높은 체력과 방어력으로 최전선에서 공격을 받아낸다. 단순하지만 안정적인 방어 역할에 충실하다.","en":"High health and defence let her absorb attacks on the front line. Simple, but utterly dependable in the defensive role.","ja":"高い体力と防御力で最前線の攻撃を受け止める。単純だが、安定した防御役に徹する。"},"img":"shield_01","r":0,"timing":[0.4,1.3]},{"id":"Shield_02","stats":{"hp":1000.0,"atk":24.0,"aspd":0.357,"range":1.5,"speed":2.0,"cost":90},"name":{"ko":"유즈","en":"Yuzu","ja":"ユズ"},"bio":{"ko":"한시도 가만히 있지 않는 밝고 통통 튀는 메이드. 무슨 일이 있어도 \"괜찮아!\"라며 웃어버리는 초긍정 성격으로 주변까지 덩달아 힘이 나게 만든다.","en":"A bright, bouncy maid who cannot sit still for a second. Whatever happens she laughs it off with an \"It's fine!\" — relentlessly upbeat, and she lifts everyone around her with it.","ja":"一時もじっとしていない、明るくはつらつとしたメイド。何があっても「大丈夫!」と笑い飛ばす超前向きな性格で、周りまでつられて元気にしてしまう。"},"ability":{"ko":"주변의 적을 도발해 자신에게 공격을 집중시킨다. 적을 붙잡아 두는 동안 다른 아군이 안전하게 공격할 수 있다.","en":"She taunts nearby enemies into focusing their attacks on her. While she pins them down, the rest of the party can attack in safety.","ja":"周囲の敵を挑発し、攻撃を自分に集中させる。敵を引きつけている間、ほかの味方が安全に攻撃できる。"},"img":"shield_02","r":1,"timing":[0.4,1.3]},{"id":"Shield_03","stats":{"hp":1450.0,"atk":32.0,"aspd":0.357,"range":1.5,"speed":2.0,"cost":125},"name":{"ko":"로젤린","en":"Roselyn","ja":"ロゼリン"},"bio":{"ko":"화려한 말투와 우아한 몸가짐이 몸에 밴 귀족풍 메이드. 다소 도도하고 거만해 보이지만, 자신이 맡은 역할만큼은 누구보다 확실하게 해낸다.","en":"An aristocratic maid whose ornate speech and graceful bearing come as second nature. She can seem haughty, even arrogant, but no one discharges her assigned duty more thoroughly than she does.","ja":"華やかな言葉遣いと優雅な立ち居振る舞いが身についた貴族風のメイド。やや高慢で気位が高く見えるが、任された役割だけは誰よりも確実にやり遂げる。"},"ability":{"ko":"넓은 범위의 적을 도발하고, 도발하는 동안 방어력이 더욱 상승한다. 장시간 전선을 유지하는 데 강하다.","en":"She taunts enemies over a wide area, and her defence rises further while the taunt holds. Excellent at holding a line for a long stretch.","ja":"広い範囲の敵を挑発し、挑発している間は防御力がさらに上昇する。長時間にわたって前線を維持するのに強い。"},"img":"shield_03","r":2,"timing":[0.4,1.3]},{"id":"Naru","stats":{"hp":620.0,"atk":20.0,"aspd":0.357,"range":1.5,"speed":2.0,"cost":60},"name":{"ko":"나루","en":"Naru","ja":"ナル"},"bio":{"ko":"모든 일에 늘 최선을 다하는 성실한 메이드. 하지만 의외로 허술한 구석이 있어 실수가 잦고, 그만큼 혼나는 일도 많다. 그래도 그 성실함과 \"헤헤…\" 하며 머리를 긁적이는 미워할 수 없는 웃음은, 지켜보는 이까지 미소 짓게 만든다.","en":"A diligent maid who always gives everything her best. Yet she is surprisingly clumsy, makes mistakes often, and gets scolded just as often. Still, her earnest effort and that impossible-to-dislike \"Ehehe...\" as she scratches her head never fail to make anyone watching smile.","ja":"どんなことにもいつも全力で取り組む、まじめなメイド。けれど意外と抜けたところがあってミスが多く、そのぶん叱られることも多い。それでも、そのひたむきさと「えへへ…」と頭をかく憎めない笑顔は、見ている人まで思わず笑顔にしてしまう。"},"ability":{"ko":"높은 체력과 방어력으로 최전선에서 공격을 받아낸다. 단순하지만 끝까지 버티는 든든한 방패 역할을 한다.","en":"High health and defence let her absorb attacks on the front line. Simple, but a sturdy shield who holds on to the very end.","ja":"高い体力と防御力で最前線の攻撃を受け止める。単純だが、最後まで踏ん張る頼もしい盾役。"},"img":"shield_naru","r":0,"backer":true,"timing":[0.4,1.3]}]},{"key":"killer","name":{"ko":"연격","en":"Killer","ja":"連撃"},"maids":[{"id":"Ayame","stats":{"hp":250.0,"atk":20.0,"aspd":1.25,"range":1.5,"speed":4.6,"cost":80},"name":{"ko":"아야메","en":"Ayame","ja":"アヤメ"},"bio":{"ko":"한 번 마음에 둔 상대는 끝까지 쫓아가는 얀데레 메이드. 자기만의 속도로 천천히 상대를 몰아붙이며, 한번 정한 일은 무슨 일이 있어도 끝장을 보려 한다.","en":"A yandere maid who will follow the one she has set her heart on to the very end. She corners her target at her own unhurried pace, and once she has decided on something she will see it through no matter what.","ja":"一度想いを寄せた相手はどこまでも追いかけるヤンデレメイド。自分のペースでじわじわと相手を追い詰め、一度こうと決めたことは何があっても最後までやり通そうとする。"},"ability":{"ko":"공격 한 번의 위력은 낮지만 매우 빠른 속도로 연속 공격을 가한다. 공격을 계속 이어갈수록 높은 화력을 낸다.","en":"Each blow lands light, but she strings them together at tremendous speed. The longer she keeps attacking, the more damage she puts out.","ja":"一撃の威力は低いが、非常に速い速度で連続攻撃を叩き込む。攻撃を続けるほど高い火力を発揮する。"},"img":"killer_01","r":0,"timing":[0.2,0.8]},{"id":"Killer_02","stats":{"hp":300.0,"atk":22.0,"aspd":1.538,"range":1.5,"speed":4.9,"cost":110},"name":{"ko":"히마리","en":"Himari","ja":"ヒマリ"},"bio":{"ko":"늘 멍한 얼굴로 조용히 서 있는 메이드. 무슨 생각을 하는지 도무지 알 수 없지만, 마음에 든 상대에 대한 집착만큼은 꽤나 무섭다.","en":"A maid who simply stands there in silence, a blank look on her face. Nobody has the faintest idea what goes on in her head — but her fixation on whoever has caught her eye is frankly frightening.","ja":"いつもぼんやりした顔で静かに立っているメイド。何を考えているのかまるで読めないが、気に入った相手への執着だけはかなり恐ろしい。"},"ability":{"ko":"공격이 적중할 때마다 공격력이 상승한다. 공격을 계속 이어갈수록 화력이 점점 강해진다.","en":"Every attack that connects raises her attack power. The longer she keeps swinging, the harder she hits.","ja":"攻撃が命中するたびに攻撃力が上昇する。攻撃を続けるほど火力がどんどん高まっていく。"},"img":"killer_02","r":1,"timing":[0.4,1.3]},{"id":"Killer_03","stats":{"hp":340.0,"atk":26.0,"aspd":2.0,"range":1.5,"speed":5.4,"cost":155},"name":{"ko":"사쿠라","en":"Sakura","ja":"サクラ"},"bio":{"ko":"항상 겁먹은 듯한 표정으로 조심스럽게 행동하는 메이드. 하지만 자신이 집착하는 상대에게 무슨 일이 생기는 순간, 평소의 분위기와는 전혀 다른 모습을 보여준다.","en":"A maid who always looks a little frightened and moves with great care. But the instant anything happens to the person she is fixated on, she becomes something else entirely.","ja":"いつも怯えたような表情で、おそるおそる行動するメイド。しかし、自分が執着している相手に何かが起きた瞬間、普段とはまるで別人のような姿を見せる。"},"ability":{"ko":"매우 빠른 공격 속도로 적을 연속 공격한다. 적을 처치할 때마다 공격 속도가 크게 상승한다.","en":"She attacks in relentless bursts at tremendous speed. Every kill sends her attack speed sharply higher.","ja":"非常に速い攻撃速度で敵を連続攻撃する。敵を倒すたびに攻撃速度が大きく上昇する。"},"img":"killer_03","r":2,"timing":[0.4,1.3]}]},{"key":"arrow","name":{"ko":"궁수","en":"Archer","ja":"弓"},"maids":[{"id":"Nagi","stats":{"hp":230.0,"atk":50.0,"aspd":0.417,"range":6.5,"speed":2.5,"cost":90},"name":{"ko":"나기","en":"Nagi","ja":"ナギ"},"bio":{"ko":"자신이 귀엽고 우월하다는 사실을 아주 잘 알고 있는 메이드. 여유롭게 상대를 내려다보며 놀리는 것을 즐기는, 당당함을 넘어 조금 얄미운 성격의 소유자다.","en":"A maid who is fully aware of how cute and how superior she is. She enjoys looking down on people at her leisure and needling them — confident to the point of being just a little insufferable.","ja":"自分が可愛くて優れているという事実を、実によく分かっているメイド。余裕たっぷりに相手を見下ろしてからかうのを楽しむ、堂々を通り越して少し憎らしい性格の持ち主。"},"ability":{"ko":"긴 사거리에서 포물선 형태의 투사체를 발사한다. 후방에서 안전하게 적을 공격한다.","en":"She lobs arcing projectiles from a long range. Attacks the enemy safely from the back line.","ja":"長い射程から放物線を描く投射物を放つ。後方から安全に敵を攻撃する。"},"img":"arrow_01","r":0,"timing":[0.4,1.3]},{"id":"Arrow_02","stats":{"hp":280.0,"atk":54.0,"aspd":0.526,"range":7.0,"speed":2.5,"cost":115},"name":{"ko":"토와","en":"Towa","ja":"トワ"},"bio":{"ko":"안광 없는 눈으로 싱글싱글 웃는 수상한 메이드. 말투도 행동도 어딘가 음침하지만, 정작 본인은 그 분위기를 꽤 마음에 들어 하는 것 같다.","en":"A suspicious maid who grins away with no light at all in her eyes. Her speech and her manner are both faintly gloomy, though she herself seems rather fond of the atmosphere she gives off.","ja":"光のない目でにこにこと笑う怪しいメイド。口調も仕草もどこか陰気だが、当の本人はその雰囲気をかなり気に入っているらしい。"},"ability":{"ko":"높은 공격 속도로 빠르게 화살을 발사한다. 후방에서 지속적인 원거리 화력을 담당한다.","en":"She looses arrows rapidly at a high rate of fire. Provides sustained ranged firepower from the back line.","ja":"高い攻撃速度で素早く矢を放つ。後方から継続的な遠距離火力を担う。"},"img":"arrow_02","r":1,"timing":[0.4,1.3]},{"id":"Arrow_03","stats":{"hp":340.0,"atk":62.0,"aspd":0.667,"range":7.5,"speed":2.5,"cost":150},"name":{"ko":"세리나","en":"Serina","ja":"セリナ"},"bio":{"ko":"맑고 단정한 분위기가 잘 어울리는 청순한 메이드. 조용하고 차분한 성격이라 전투 중에도 크게 동요하지 않고 자신의 역할을 끝까지 해낸다.","en":"A demure maid whom a clean, composed air suits perfectly. Quiet and level-headed, she does not rattle easily even mid-battle and sees her role through to the end.","ja":"清らかで端正な雰囲気がよく似合う清楚なメイド。静かで落ち着いた性格なので、戦闘中も大きく取り乱すことなく、自分の役割を最後まで果たす。"},"ability":{"ko":"긴 사거리와 빠른 연사 능력을 갖추고 있다. 공격에 맞은 적의 이동 속도를 일정 시간 감소시킨다.","en":"She combines long range with a rapid rate of fire. Enemies she hits have their movement speed reduced for a time.","ja":"長い射程と速い連射能力を併せ持つ。攻撃が命中した敵の移動速度を一定時間低下させる。"},"img":"arrow_03","r":2,"timing":[0.4,1.3]}]},{"key":"gunner","name":{"ko":"총격","en":"Gunner","ja":"銃撃"},"maids":[{"id":"Gunner_01","stats":{"hp":260.0,"atk":70.0,"aspd":0.385,"range":4.0,"speed":2.4,"cost":105},"name":{"ko":"사츠키","en":"Satsuki","ja":"サツキ"},"bio":{"ko":"날카로운 눈빛과 까칠한 말투가 인상적인 흑발 메이드. 사소한 것에도 쉽게 만족하지 않는 성격이라, 마음에 들지 않는 건 바로 지적하고 본다.","en":"A black-haired maid with a sharp gaze and an equally sharp tongue. Nothing small is ever quite good enough for her, and whatever she dislikes she points out on the spot.","ja":"鋭い眼差しと刺のある口調が印象的な黒髪のメイド。細かなことにもなかなか満足しない性格で、気に入らないものはその場ですぐ指摘する。"},"ability":{"ko":"중거리에서 강한 직사 공격을 가한다. 사거리를 유지하면서 단일 대상에게 높은 피해를 안정적으로 넣는다.","en":"She fires hard-hitting direct shots at mid range. Holds her distance and lands high single-target damage reliably.","ja":"中距離から強力な直射攻撃を放つ。射程を保ちながら、単体に高いダメージを安定して与える。"},"img":"gunner_01","r":0,"timing":[0.4,1.3]},{"id":"Gunner_02","stats":{"hp":310.0,"atk":95.0,"aspd":0.4,"range":4.3,"speed":2.4,"cost":135},"name":{"ko":"유리","en":"Yuri","ja":"ユリ"},"bio":{"ko":"한쪽 눈을 가린 단발머리 메이드. 감정도 말수도 적어서 차갑게 느껴지지만, 불필요한 말을 하지 않을 뿐 나름대로 주변을 잘 관찰하고 있다.","en":"A short-haired maid with one eye hidden behind her bangs. She shows little emotion and says even less, which reads as cold — but she simply avoids unnecessary words while watching everything around her closely.","ja":"片目を隠したショートヘアのメイド。感情も口数も少なく冷たく見えるが、無駄な言葉を口にしないだけで、彼女なりに周囲をよく観察している。"},"ability":{"ko":"공격한 적을 강하게 밀어낸다. 접근해 오는 적의 움직임을 끊고 전선을 안정시키는 데 유리하다.","en":"Her shots shove the enemy hard backwards. Good for breaking up an approach and steadying the front line.","ja":"攻撃した敵を強く押し戻す。接近してくる敵の動きを断ち切り、前線を安定させるのに向いている。"},"img":"gunner_02","r":1,"timing":[0.4,1.3]},{"id":"Gunner_03","stats":{"hp":380.0,"atk":120.0,"aspd":0.417,"range":4.6,"speed":2.4,"cost":175},"name":{"ko":"노아","en":"Noa","ja":"ノア"},"bio":{"ko":"언제나 조금 졸린 듯한 눈으로 세상을 바라보는 과묵한 메이드. 귀찮은 건 질색하면서도, 해야 할 일이 생기면 느릿느릿한 손으로도 정확하게 끝내놓는다.","en":"A taciturn maid who looks at the world through perpetually sleepy eyes. She cannot stand anything troublesome, yet when there is a job to do she finishes it precisely, however slowly her hands move.","ja":"いつも少し眠たげな目で世界を眺めている寡黙なメイド。面倒なことは大の苦手なのに、やるべきことができると、のろのろとした手つきでも正確に片づけてしまう。"},"ability":{"ko":"체력이 크게 떨어진 적을 일정 확률로 즉시 처치한다. 약해진 적을 빠르게 정리하는 데 특화되어 있다.","en":"Enemies at very low health may be finished off instantly. Specialised in clearing away weakened targets fast.","ja":"体力が大きく減った敵を一定確率で即座に倒す。弱った敵を素早く始末することに特化している。"},"img":"gunner_03","r":2,"timing":[0.4,1.3]}]},{"key":"magician","name":{"ko":"마법","en":"Magician","ja":"魔法"},"maids":[{"id":"Magician_01","stats":{"hp":280.0,"atk":46.0,"aspd":0.333,"range":5.0,"speed":2.3,"cost":120},"name":{"ko":"노엘","en":"Noel","ja":"ノエル"},"bio":{"ko":"감정의 변화가 거의 없는 무표정 메이드. 마치 정교하게 만들어진 인형처럼 차분하게 움직이며, 불길을 만들어내는 순간에도 표정 하나 변하지 않는다.","en":"An expressionless maid whose mood barely shifts at all. She moves with the composure of a finely made doll, and not a flicker crosses her face even as she calls up the flames.","ja":"感情の起伏がほとんどない無表情なメイド。精巧に作られた人形のように淡々と動き、炎を生み出す瞬間ですら表情ひとつ変えない。"},"ability":{"ko":"화염 마법으로 착탄 지점 주변을 폭발시킨다. 적이 몰려 있을수록 높은 광역 피해를 준다.","en":"Her fire magic bursts around the point of impact. The more tightly the enemy is packed, the more area damage it deals.","ja":"炎の魔法で着弾地点の周囲を爆発させる。敵が密集しているほど高い範囲ダメージを与える。"},"img":"magician_01","r":0,"timing":[0.4,1.3]},{"id":"Magician_02","stats":{"hp":340.0,"atk":60.0,"aspd":0.345,"range":5.5,"speed":2.3,"cost":165},"name":{"ko":"세레나","en":"Serena","ja":"セレナ"},"bio":{"ko":"따뜻한 미소와 여유로운 분위기가 돋보이는 언니 타입의 메이드. 언제나 아군을 다정하게 챙기지만, 전투에서는 누구보다 강력한 전격을 내리꽂는다.","en":"A big-sister type whose warm smile and unhurried air stand out anywhere. She looks after her allies with genuine affection — and then brings down lightning harder than anyone else on the field.","ja":"温かな微笑みとゆとりある雰囲気が際立つ、姉御肌のメイド。いつも味方を優しく気遣うが、戦いでは誰よりも強力な雷撃を叩き込む。"},"ability":{"ko":"넓은 범위에 강력한 전격 마법을 가한다. 여러 적을 동시에 공격하는 광역 공격형이다.","en":"She strikes a wide area with powerful lightning magic. An area attacker that hits many enemies at once.","ja":"広い範囲に強力な雷撃魔法を放つ。複数の敵を同時に攻撃する範囲攻撃型。"},"img":"magician_02","r":1,"timing":[0.4,1.3]},{"id":"Magician_03","stats":{"hp":420.0,"atk":80.0,"aspd":0.357,"range":6.0,"speed":2.3,"cost":230},"name":{"ko":"루시아","en":"Lucia","ja":"ルシア"},"bio":{"ko":"마법이라면 뭐든 알고 싶어 하는 자칭 최고 마법 덕후. 평소엔 조용하지만 새로운 마법 이야기가 나오면 눈빛부터 달라진다.","en":"A self-proclaimed magic obsessive who wants to know everything there is to know about spellcraft. Quiet most of the time — until new magic comes up, at which point her eyes change entirely.","ja":"魔法のことなら何でも知りたがる自称・最強の魔法オタク。普段は物静かだが、新しい魔法の話が出た途端に目の色が変わる。"},"ability":{"ko":"강력한 얼음 마법으로 넓은 범위를 공격한다. 적이 모여 있는 구간을 한 번에 정리할 수 있다.","en":"She attacks a wide area with powerful ice magic. Capable of clearing a whole cluster of enemies in one go.","ja":"強力な氷の魔法で広い範囲を攻撃する。敵が集まっている一帯を一度に片づけられる。"},"img":"magician_03","r":2,"timing":[0.4,1.3]}]},{"key":"boomer","name":{"ko":"자폭","en":"Boomer","ja":"自爆"},"maids":[{"id":"Boomer_01","stats":{"hp":230.0,"atk":130.0,"aspd":1.0,"range":1.4,"speed":3.9,"cost":75},"name":{"ko":"하나비","en":"Hanabi","ja":"ハナビ"},"bio":{"ko":"늘 정신없이 당황하는 메이드. 겁을 잔뜩 먹고 허둥대면서도 어째서인지 적에게는 꾸역꾸역 가까이 다가간다.","en":"A maid in a permanent state of flustered panic. Terrified and flapping about, she nonetheless keeps inching closer and closer to the enemy, for reasons no one can explain.","ja":"いつも慌てふためいているメイド。すっかり怯えてあたふたしているのに、なぜか敵にはじりじりと近づいていく。"},"ability":{"ko":"적에게 접근한 뒤 스스로 폭발하여 주변에 큰 피해를 준다. 자신의 생존보다 한 번의 강력한 공격을 중시한다.","en":"She closes on the enemy and detonates herself, dealing heavy damage all around. She values one devastating blow over her own survival.","ja":"敵に接近したあと自ら爆発し、周囲に大きなダメージを与える。自身の生存より、一度の強力な攻撃を重んじる。"},"img":"boomer_01","r":0},{"id":"Boomer_02","stats":{"hp":290.0,"atk":190.0,"aspd":1.0,"range":1.4,"speed":3.9,"cost":120},"name":{"ko":"미오","en":"Mio","ja":"ミオ"},"bio":{"ko":"눈에 하트가 떠오를 만큼 사랑에 푹 빠져 있는 메이드. 한번 마음에 든 상대라면 절대로 놓아주지 않으며, 가까이 있을수록 행복해하는 위험한 집착형이다.","en":"A maid so deep in love that hearts all but float in her eyes. She never lets go of anyone she has taken a liking to, and the closer she gets the happier she becomes — a dangerously obsessive type.","ja":"目にハートが浮かぶほど恋に落ちきっているメイド。一度気に入った相手は決して離さず、近くにいればいるほど幸せそうにする、危険な執着型。"},"ability":{"ko":"적에게 접근해 강력한 자폭 공격을 가한다. 다수의 적이 모여 있을수록 높은 효율을 보인다.","en":"She closes in and delivers a powerful self-destructing blast. The more enemies bunched together, the better she performs.","ja":"敵に接近し、強力な自爆攻撃を放つ。敵が多く固まっているほど高い効率を発揮する。"},"img":"boomer_02","r":1},{"id":"Boomer_03","stats":{"hp":350.0,"atk":240.0,"aspd":1.0,"range":1.4,"speed":3.9,"cost":175},"name":{"ko":"키라라","en":"Kirara","ja":"キララ"},"bio":{"ko":"눈에 별이 반짝일 정도로 호기심이 왕성한 메이드. 위험하다는 말을 들어도 일단 직접 확인해 보고 싶어 하는, 조금 모자라지만 사랑스러운 성격이다.","en":"A maid whose curiosity is so boundless her eyes practically sparkle. Tell her something is dangerous and she still wants to go and check for herself — a little short on sense, but endearing all the same.","ja":"目に星が輝くほど好奇心旺盛なメイド。危ないと言われても、とりあえず自分の目で確かめてみたくなる、少し足りないけれど愛らしい性格。"},"ability":{"ko":"강력한 광역 자폭을 일으켜 주변의 적을 한꺼번에 공격한다. 적이 몰려 있을수록 효과적이다.","en":"She sets off a powerful wide-area self-destruct that catches every enemy nearby at once. The more the enemy clusters, the better it works.","ja":"強力な広範囲の自爆を起こし、周囲の敵をまとめて攻撃する。敵が密集しているほど効果的。"},"img":"boomer_03","r":2}]},{"key":"breaker","name":{"ko":"파쇄","en":"Breaker","ja":"破砕"},"maids":[{"id":"Breaker_01","stats":{"hp":440.0,"atk":95.0,"aspd":0.417,"range":1.8,"speed":2.7,"cost":95},"name":{"ko":"유이","en":"Yui","ja":"ユイ"},"bio":{"ko":"조금 어수룩해 보이지만 이상할 정도로 자신감이 넘치는 메이드. 무슨 일이 벌어져도 일단 \"괜찮아!\"라고 외치며 당당하게 밀어붙이는 타입이다.","en":"She comes across as a bit of a scatterbrain, yet her confidence is oddly unshakeable. Whatever goes wrong, her first move is to shout \"It's fine!\" and barrel straight ahead.","ja":"少し抜けているように見えるのに、なぜか自信だけは異様にあふれているメイド。何が起きてもとりあえず「大丈夫!」と叫んで、堂々と押し通すタイプ。"},"ability":{"ko":"적 유닛을 무시하고 적 기지로 곧장 이동한다. 전투보다 기지 파괴에 집중하는 특수한 역할을 맡는다.","en":"She ignores enemy units and walks straight for the enemy base. A specialist role focused on demolition rather than combat.","ja":"敵ユニットを無視して敵拠点へまっすぐ向かう。戦闘ではなく拠点破壊に専念する特殊な役割を担う。"},"img":"breaker_01","r":0,"timing":[0.4,1.3]},{"id":"Breaker_02","stats":{"hp":540.0,"atk":120.0,"aspd":0.556,"range":1.8,"speed":2.8,"cost":135},"name":{"ko":"코하루","en":"Koharu","ja":"コハル"},"bio":{"ko":"무슨 일만 생기면 금세 \"어떡하지, 어떡하지...\" 하고 안절부절못하는 소심한 메이드. 허둥대는 모습과는 달리, 목표가 정해지면 누구보다 성실하게 움직인다.","en":"The moment anything happens she starts fretting — \"What do I do, what do I do…\" — and cannot keep still. For all the flapping, once she has a target she works at it more diligently than anyone.","ja":"何かあるとすぐに「どうしよう、どうしよう…」とおろおろしてしまう気の小さいメイド。慌てふためく姿とは裏腹に、目標さえ決まれば誰よりも真面目に動く。"},"ability":{"ko":"빠른 공격 속도로 적 기지를 집중 공격한다. 교전보다 기지 철거에 높은 효율을 보인다.","en":"She hammers the enemy base with a fast attack rate. Far more efficient at demolition than at fighting.","ja":"速い攻撃速度で敵拠点を集中攻撃する。交戦よりも拠点の解体で高い効率を発揮する。"},"img":"breaker_02","r":1,"timing":[0.4,1.3]},{"id":"Breaker_03","stats":{"hp":680.0,"atk":150.0,"aspd":0.714,"range":1.8,"speed":3.6,"cost":185},"name":{"ko":"료","en":"Ryo","ja":"リョウ"},"bio":{"ko":"말투부터 성격까지 꽤나 까칠하고 사나운 메이드. 얌전히 지나가는 법이 없어 보이는 상대가 있으면 굳이 시비를 걸고 지나간다.","en":"Sharp-tongued and rough-edged, from the way she talks to the way she acts. She never simply walks past anyone — spot someone in her way and she will go out of her way to pick a fight first.","ja":"口調から性格まで、なかなかに刺々しく荒っぽいメイド。おとなしく通り過ぎることがなく、目についた相手がいればわざわざ因縁をつけてから行く。"},"ability":{"ko":"높은 이동 속도와 공격 속도를 갖춘 철거형 전투원. 적 기지에 빠르게 접근해 짧은 시간에 큰 피해를 준다.","en":"A demolition fighter with high movement and attack speed. She reaches the enemy base fast and deals heavy damage in a short window.","ja":"高い移動速度と攻撃速度を備えた解体型の戦闘員。敵拠点へ素早く到達し、短時間で大きな被害を与える。"},"img":"breaker_03","r":2,"timing":[0.4,1.3]}]},{"key":"heal","name":{"ko":"치유","en":"Healer","ja":"回復"},"maids":[{"id":"Iroha","stats":{"hp":300.0,"atk":5.0,"aspd":0.357,"range":5.5,"speed":2.5,"cost":75},"name":{"ko":"이로하","en":"Iroha","ja":"イロハ"},"bio":{"ko":"누구에게나 따뜻하고 다정하게 대하는 천사 같은 메이드. 작은 상처 하나도 그냥 지나치지 않는 섬세함으로 늘 아군을 살핀다.","en":"An angel of a maid who treats everyone with warmth and kindness. Attentive enough to notice the smallest scrape, she keeps a constant eye on her allies.","ja":"誰に対しても温かく優しく接する、天使のようなメイド。小さな傷ひとつ見逃さない細やかさで、いつも味方を気にかけている。"},"ability":{"ko":"가장 크게 다친 아군 한 명을 집중적으로 회복한다. 안정적인 단일 대상 치유를 담당한다.","en":"She concentrates her healing on the single most badly wounded ally. A steady, reliable single-target healer.","ja":"最も大きな傷を負った味方一人を集中的に回復する。安定した単体回復を担当する。"},"img":"heal_01","r":0,"timing":[0.4,1.3]},{"id":"Heal_02","stats":{"hp":380.0,"atk":5.0,"aspd":0.385,"range":6.0,"speed":2.5,"cost":130},"name":{"ko":"카렌","en":"Karen","ja":"カレン"},"bio":{"ko":"겉으로는 도도하고 까칠해 보여도 사실은 누구보다 상냥한 메이드. 직접적인 칭찬을 받으면 괜히 퉁명스럽게 굴며 얼굴을 붉힌다.","en":"She may come across as aloof and prickly, but underneath she is kinder than anyone. Praise her to her face and she turns brusque and goes red at the same time.","ja":"見た目はツンとしてきつそうなのに、実際は誰よりも優しいメイド。面と向かって褒められると、わざとそっけない態度を取りながら顔を赤らめる。"},"ability":{"ko":"가장 크게 피해를 입은 아군 둘을 동시에 회복한다. 여러 아군의 체력을 안정적으로 유지한다.","en":"She heals the two most badly hurt allies at the same time. Keeps several allies topped up dependably.","ja":"最も大きな被害を受けた味方二人を同時に回復する。複数の味方の体力を安定して維持する。"},"img":"heal_02","r":1,"timing":[0.4,1.3]},{"id":"Heal_03","stats":{"hp":460.0,"atk":5.0,"aspd":0.417,"range":6.5,"speed":2.5,"cost":200},"name":{"ko":"나츠메","en":"Natsume","ja":"ナツメ"},"bio":{"ko":"뭘 하든 귀찮다는 표정으로 졸고 있는 보라머리 트윈테일 메이드. 가능하면 움직이고 싶지 않아 하지만, 정말 필요한 순간에는 결국 치료해준다.","en":"A purple-haired maid in twintails who dozes through everything with a look of pure inconvenience. She would rather not move if she can help it, but when it truly matters she comes through with the healing.","ja":"何をするにも面倒くさそうな顔でうとうとしている、紫髪ツインテールのメイド。できれば動きたくないと思っているが、本当に必要な場面では結局ちゃんと治してくれる。"},"ability":{"ko":"아군 셋을 동시에 크게 회복한다. 다수의 아군이 큰 피해를 입은 상황에서 특히 강력하다.","en":"She heals three allies at once, and heals them heavily. Especially strong when much of the party has taken a beating.","ja":"味方三人を同時に大きく回復する。多くの味方が大きな被害を受けた状況で特に強力。"},"img":"heal_03","r":2,"timing":[0.4,1.3]}]},{"key":"buffer","name":{"ko":"강화","en":"Buffer","ja":"強化"},"maids":[{"id":"Buffer_01","stats":{"hp":340.0,"atk":12.0,"aspd":0.333,"range":2.0,"speed":2.5,"cost":70},"name":{"ko":"치하야","en":"Chihaya","ja":"チハヤ"},"bio":{"ko":"장난칠 기회만 보이면 절대 놓치지 않는 짓궂은 메이드. 능글맞게 웃으며 남을 놀리는 걸 좋아하지만, 의외로 주변 사람을 꽤 잘 챙긴다.","en":"A mischievous maid who never lets an opportunity for a prank slip by. She loves teasing people with a sly grin — and yet, surprisingly, she looks after those around her rather well.","ja":"いたずらの機会を見つけたら絶対に逃さない、意地の悪いメイド。にやにやしながら人をからかうのが好きだが、意外にも周りの人の面倒をかなりよく見る。"},"ability":{"ko":"가까운 아군 한 명의 공격력을 높인다. 공격력이 높은 전투원과 함께 배치하면 효과가 크다.","en":"She raises the attack power of one nearby ally. Most effective when paired with a high-attack fighter.","ja":"近くの味方一人の攻撃力を高める。攻撃力の高い戦闘員と一緒に配置すると効果が大きい。"},"img":"buffer_01","r":0,"timing":[0.4,1.3]},{"id":"Buffer_02","stats":{"hp":460.0,"atk":16.0,"aspd":0.333,"range":2.0,"speed":2.5,"cost":140},"name":{"ko":"모미지","en":"Momiji","ja":"モミジ"},"bio":{"ko":"밝고 귀여운 성격에 누구에게나 친절한 메이드. 먼저 다가가는 걸 어려워하지 않아, 어느새 모두와 친해져 있는 경우가 많다.","en":"A cheerful, adorable maid who is kind to absolutely everyone. She has no trouble making the first approach, so more often than not she has already befriended the whole room.","ja":"明るくて可愛らしい性格で、誰にでも親切なメイド。自分から声をかけるのを苦にしないので、気づけば全員と仲良くなっていることが多い。"},"ability":{"ko":"아군 셋의 공격력과 공격 속도를 동시에 높인다. 여러 전투원을 함께 강화할 수 있다.","en":"She raises the attack power and attack speed of three allies at once. Can strengthen several fighters together.","ja":"味方三人の攻撃力と攻撃速度を同時に高める。複数の戦闘員をまとめて強化できる。"},"img":"buffer_02","r":1,"timing":[0.4,1.3]},{"id":"Yuki","stats":{"hp":680.0,"atk":40.0,"aspd":0.333,"range":2.0,"speed":2.5,"cost":190},"name":{"ko":"유키","en":"Yuki","ja":"ユキ"},"bio":{"ko":"선글라스까지 쓰고 느긋하게 웃고 있는 유쾌한 메이드. 위험한 일은 최대한 남에게 떠넘기고 뒤로 빠지지만, 덕분에 살아남는 법 하나만큼은 확실히 알고 있다.","en":"A carefree maid, sunglasses and all, forever wearing an easy grin. She palms off anything dangerous onto someone else and hangs back — which is precisely why she knows exactly how to survive.","ja":"サングラスまでかけて、のんびり笑っている愉快なメイド。危ない仕事はできる限り人に押しつけて後ろに下がるが、おかげで生き延びる術だけは確実に心得ている。"},"ability":{"ko":"자신은 공격하지 않고 주변 아군의 공격력을 강화한다. 넓은 범위의 전투원을 동시에 지원한다.","en":"She never attacks herself; instead she strengthens the attack power of nearby allies. Supports fighters across a wide area at once.","ja":"自分では攻撃せず、周囲の味方の攻撃力を強化する。広い範囲の戦闘員を同時に支援する。"},"img":"buffer_03","r":2,"timing":[0.4,1.3]}]},{"key":"debuffer","name":{"ko":"약화","en":"Debuffer","ja":"弱体"},"maids":[{"id":"Nozomi","stats":{"hp":330.0,"atk":22.0,"aspd":0.357,"range":6.0,"speed":2.5,"cost":80},"name":{"ko":"노조미","en":"Nozomi","ja":"ノゾミ"},"bio":{"ko":"시끌벅적한 곳보다는 조용하고 편안한 곳을 좋아하는 메이드. 느긋하게 지내는 걸 좋아하면서도, 주변 사람을 챙기는 일만큼은 은근히 부지런하다.","en":"A maid who prefers somewhere quiet and comfortable to anywhere noisy. She likes taking things easy, and yet when it comes to looking after the people around her she is quietly diligent.","ja":"賑やかな場所よりも、静かで落ち着ける場所を好むメイド。のんびり過ごすのが好きなくせに、周りの人の世話を焼くことにだけはさりげなくまめである。"},"ability":{"ko":"직선으로 날아가는 투사체를 적중시켜 적의 공격력을 감소시킨다. 적의 화력을 낮추는 데 특화되어 있다.","en":"She fires a projectile in a straight line that lowers the attack power of whatever it hits. Specialised in blunting the enemy's firepower.","ja":"直線に飛ぶ投射物を命中させ、敵の攻撃力を低下させる。敵の火力を下げることに特化している。"},"img":"debuffer_01","r":0,"timing":[0.4,1.3]},{"id":"Debuffer_02","stats":{"hp":420.0,"atk":30.0,"aspd":0.385,"range":6.0,"speed":2.5,"cost":110},"name":{"ko":"쿠로에","en":"Kuroe","ja":"クロエ"},"bio":{"ko":"말수가 적고 감정을 거의 드러내지 않는 메이드. 무심한 얼굴로 상황을 지켜보다가, 상대가 가장 아픈 곳을 정확하게 찔러낸다.","en":"A maid of few words who shows almost nothing of what she feels. She watches a situation unfold with an indifferent face, then puts her finger exactly on the sorest spot.","ja":"口数が少なく、感情をほとんど表に出さないメイド。無関心そうな顔で状況を眺めていて、相手の一番痛いところを正確に突いてくる。"},"ability":{"ko":"적의 이동 속도와 공격력, 방어력을 함께 낮춘다. 한 번에 여러 능력치를 약화시켜 전투력을 크게 떨어뜨린다.","en":"She lowers the enemy's movement speed, attack power and defence together. Weakening several stats at once cuts their combat strength sharply.","ja":"敵の移動速度、攻撃力、防御力をまとめて低下させる。一度に複数の能力を弱体化させ、戦闘力を大きく削ぐ。"},"img":"debuffer_02","r":1,"timing":[0.4,1.3]},{"id":"Debuffer_03","stats":{"hp":520.0,"atk":46.0,"aspd":0.4,"range":6.2,"speed":2.5,"cost":145},"name":{"ko":"모카","en":"Moka","ja":"モカ"},"bio":{"ko":"밝고 당당한 분위기의 자신감 넘치는 메이드. 처음 만난 상대에게도 거리낌 없이 말을 걸 정도로 친근하며, 웬만한 상황에서는 쉽게 주눅 들지 않는다.","en":"A bright, self-assured maid who carries herself with real confidence. Friendly enough to strike up a conversation with a total stranger, and not much rattles her.","ja":"明るく堂々とした雰囲気の、自信にあふれたメイド。初対面の相手にも気軽に話しかけるほど人懐っこく、たいていの状況では簡単に萎縮しない。"},"ability":{"ko":"적에게 걸린 강화 효과를 제거한 뒤 공격력과 방어력을 크게 낮춘다. 이동 속도까지 감소시켜 상대의 전투력을 전반적으로 약화한다.","en":"She strips the buffs off an enemy, then sharply lowers their attack power and defence. She slows them as well, dragging their overall combat strength down.","ja":"敵にかかっている強化効果を取り除いたうえで、攻撃力と防御力を大きく低下させる。移動速度まで下げ、相手の戦闘力を全体的に弱める。"},"img":"debuffer_03","r":2,"timing":[0.4,1.3]}]}],"quotes":{"rin":{"ko":["아버지는 차트에 인생을 걸었지만….\n난 내 손에 걸기로 했어.","이 굳은살 네 개, 훈장이나 다름없어.\n전부 곡괭이로 하나하나 새긴 거라구!","왜, 왜 자꾸 쳐다봐?\n…딱히 싫다는 건 아니지만."],"en":["Father bet his life on the charts...\nMe? I'm betting on these hands.","These four calluses are as good as medals.\nEvery one of them carved by my own pickaxe!","W-why do you keep staring?\n...Not that I mind, exactly."],"ja":["お父様はチャートに人生を賭けたけど…。\n私は自分の手に賭けることにしたの。","このタコ4つ、勲章みたいなものよ。\n全部ツルハシで一つずつ刻んだんだから！","な、なんでそんなに見るのよ？\n…別に、嫌ってわけじゃないけど。"]},"shizuka":{"ko":["검을 쥐는 법은 배웠습니다만.\n찻잔을 쥐는 법은… 아직 연습 중입니다.","…죄송합니다.\n아침은… 조금, 무리입니다….","방금 그 말씀은… 농담이었습니까?\n…이해하는 데 3초가 걸렸습니다."],"en":["I was taught how to hold a sword.\nHow to hold a teacup... I am still practising.","...My apologies.\nMornings are... slightly... beyond me...","Was that just now... a joke?\n...It took me three seconds to process."],"ja":["剣の握り方は教わりました。\nティーカップの持ち方は…まだ練習中です。","…申し訳ありません。\n朝は…少々、無理です…。","先ほどのお言葉は…冗談、でしたか？\n…理解に3秒かかりました。"]},"maki":{"ko":["지금이 저점입니다.","숫자는 거짓말을 하지 않습니다.\n거짓말은… 사람이 하는 거죠.","밤새 장부를 정리했더니….\n괜찮습니다. 커피가 있으니까요."],"en":["Now is the bottom.","Numbers never lie.\nPeople do.","I was up all night with the ledgers...\nI'm fine. There's coffee."],"ja":["今が底値です。","数字は嘘をつきません。\n嘘をつくのは…人間の方です。","徹夜で帳簿を整理していたら…。\n大丈夫です、コーヒーがありますから。"]},"akane":{"ko":["오늘 제일 만만한 집, 벌써 찍어 놨어.","옆집이랑 헷갈린 건 딱 두 번뿐이라구!\n…어라, 세 번이었나?","자물쇠 따는 거, 배워 볼래?\n…농담이야. 아니, 반쯤은 진담."],"en":["Already picked out today's easiest mark.","I only mixed up the neighbors' house twice, okay!?\n...Wait, was it three times?","Want to learn how to pick a lock?\n...Kidding. Well, half kidding."],"ja":["今日いちばんチョロい家、もう目星つけてあるよ。","隣の家と間違えたのは2回だけだってば！\n…あれ、3回だっけ？","鍵開け、習ってみる？\n…冗談だって。いや、半分は本気。"]}},"rarity":{"ko":["일반","고급","레어"],"en":["Common","Uncommon","Rare"],"ja":["コモン","アンコモン","レア"]}};
